functions using inferred-param lambdas with lang-lib map(), function-typed
values and type tests. Stage 5-9 runs concurrently across modules and across
function bodies, all funnelling through semtypes.internBddNodeKey's global
mutex."""
import os
import sys

modules = int(sys.argv[1]) if len(sys.argv) > 1 else 8
fns = int(sys.argv[2]) if len(sys.argv) > 2 else 600
root = sys.argv[3] if len(sys.argv) > 3 else "bddpkg"

os.makedirs(root, exist_ok=True)
with open(os.path.join(root, "Ballerina.toml"), "w") as fh:
    fh.write('[package]\norg = "perf"\nname = "bddpkg"\nversion = "0.1.0"\n')

for m in range(modules):
    d = os.path.join(root, "modules", f"mod{m}")
    os.makedirs(d, exist_ok=True)
    parts = [f"""public type Point record {{| int x; int y; |}};
public type Shape Point|int[]|map<int>;
"""]
    for i in range(fns):
        parts.append(f"""
function f{i}(int[] xs, Point p, Shape s) returns int {{
    int[] ys = xs.map(x => x + {i});
    int[] zs = ys.map(y => y - p.x);
    int total = zs.length();
    function (int) returns int g = a => a * p.y;
    if s is Point {{
        total += s.x + g(s.y);
    }} else if s is int[] {{
        total += s.length();
    }}
    return total + g({i});
}}
""")
