public function run() returns int {{
    Point p = {{x: 1, y: 2}};
    return f0([1, 2, 3], p, p) + f{fns - 1}([1, 2, 3], p, [4, 5]);
}}
""")
    with open(os.path.join(d, "mod.bal"), "w") as fh:
        fh.write("".join(parts))

imports = "".join(f"import perf/bddpkg.mod{m};\n" for m in range(modules))
calls = "".join(f"    acc += mod{m}:run();\n" for m in range(modules))
with open(os.path.join(root, "main.bal"), "w") as fh:
    fh.write(f"import ballerina/io;\n{imports}\npublic function main() {{\n    int acc = 0;\n{calls}    io:println(acc);\n}}\n")

